import { useMemo, useState } from "react";
import { AgGridProvider, AgGridReact } from "ag-grid-react";
import type { ColDef } from "ag-grid-community";
import { AllEnterpriseModule } from "ag-grid-enterprise";
import { AgChartsCommunityModule } from "ag-charts-community";

// All Enterprise features, with Integrated Charts powered by AG Charts Community
const modules = [AllEnterpriseModule.with(AgChartsCommunityModule)];

interface Sale {
  region: string;
  product: string;
  quarter: string;
  revenue: number;
  units: number;
}

export function SalesPivot() {
  const [rowData] = useState<Sale[]>([
    { region: "North", product: "Laptops", quarter: "Q1", revenue: 120000, units: 140 },
    { region: "North", product: "Monitors", quarter: "Q2", revenue: 48000, units: 210 },
    { region: "South", product: "Laptops", quarter: "Q1", revenue: 95000, units: 110 },
    { region: "South", product: "Monitors", quarter: "Q2", revenue: 52000, units: 230 },
  ]);

  const columnDefs = useMemo<ColDef<Sale>[]>(
    () => [
      { field: "region", rowGroup: true, enableRowGroup: true },
      { field: "product", enableRowGroup: true, enablePivot: true },
      { field: "quarter", pivot: true, enablePivot: true },
      { field: "revenue", aggFunc: "sum", enableValue: true },
      { field: "units", aggFunc: "sum", enableValue: true },
    ],
    [],
  );

  return (
    <AgGridProvider modules={modules}>
      <div style={{ height: 500 }}>
        <AgGridReact<Sale>
          rowData={rowData}
          columnDefs={columnDefs}
          pivotMode
          sideBar="columns"
          pivotPanelShow="always"
          pivotRowTotals="after"
          grandTotalRow="bottom"
          enableCharts
        />
      </div>
    </AgGridProvider>
  );
}
